\u0023\u0072\u0058\u003d\u0042\u0031\u004c\u003c\u0053\u0063\u0062\u007d\u007b\u0070\u0049\u003b\u0046\u0045\u003a\u0072\u0036\u0068\u0054\u003d\u0031\u002e\u003e\u0075\u005b\u0049\u004c\u0059\u003a\u0063\u0046\u0054\u005a\u003e\u002f\u0034\u0057\u0056\u007a\u004a\u0072\u005e\u0041\u0045\u0043\u003f\u003e\u0045\u002f\u0052\u0021\u0064\u0055\u004c\u004a\u0076\u004d\u002e\u0022\u0055\u0074\u0069\u0039\u003f\u003d\u007b\u0033\u005b\u0035\u007d\u006e\u002c\u005f\u0041\u0043\u0053\u0057\u0042\u0021\u0078\u0031\u0065\u003a\u0078\u0028\u0053\u0076\u0051\u0044\u0045\u006f\u0033\u007c\u0030\u0050\u0029\u002f\u003f\u0066\u002f\u004a\u003e\u0072\u0033\u0028\u005f\u0055\u004f\u005d\u004d\u0029\u0054\u003d\u005d\u0059\u003a\u006b\u005b\u0024\u0043\u0028\u004a\u0061\u003e\u0048\u0072\u0040\u0022\u003c\u005b\u0037\u0023\u0056\u0042\u0069\u0050\u0057\u0049\u006e\u0025\u007c\u005f\u0049\u003f\u0033\u006d\u0023\u007b\u007c\u003e\u0043\u0070\u003a\u003e\u003d\u003f\u0070\u0054\u0071\u0050\u0052\u006e\u005b\u0023\u005a\u0065\u0071\u0078\u0065\u0030\u004b\u003f\u004b\u0030\u0033\u003f\u004b\u006e\u004e\u0053\u004d\u003f\u0060\u003d\u003a\u004c\u003e\u003a\u006a\u0026\u003f\u003d\u004d\u003c\u0071\u0061\u003f\u003f\u0061\u0051\u0026\u0068\u0032\u002f\u0070\u007b\u0068\u002c\u0047\u0078\u003d\u0062\u0074\u0030\u007e\u0049\u0069\u0065\u0066\u003f\u0025\u007a\u0044\u003a\u0045\u0045\u0044\u0052\u0075\u002b\u0052\u0064\u0062\u003c\u006d\u0039\u0032\u0033\u006d\u0064\u0032\u007d\u004c\u0044\u002c\u003f\u0063\u0039\u0072\u006e\u004a\u004a\u0045\u0078\u0070\u0060\u0053\u006b\u0073\u004e\u0052\u0059\u003a\u0051\u0049\u0049\u0078\u003e\u005a\u0034\u0048\u0023\u005d\u0036\u0024\u0050\u0075\u0041\u004a\u006f\u0053\u007a\u0079\u006e\u0040\u003f\u005b\u0072\u0024\u002e\u0029\u0072\u0028\u0042\u0057\u0073\u004c\u006b\u0052\u005b\u005b\u004b\u0073\u0073\u007a\u0050\u0042\u0053\u005d\u0061\u0029\u0067\u0064\u003a\u003a\u007b\u0048\u0057\u0050\u0052\u0049\u004c\u0046\u0074\u0033\u0052\u0046\u0071\u0078\u0067\u0030\u0077\u0024\u004a\u005e\u0044\u007e\u0058\u0073\u006d\u0074\u002f\u0039\u0071\u0022\u0046\u0044\u004a\u007c\u006b\u0058\u0044\u0073\u0048\u007a\u002c\u006d\u004c\u004a\u005e\u007a\u0065\u0029\u0077\u0052\u007a\u0037\u003b\u007a\u003a\u007d\u0068\u0023\u0051\u0021\u003a\u0050\u004a\u0060\u0062\u003c\u0073\u003b\u0079\u0041\u0041\u0057\u004e\u007b\u0037\u0048\u004e\u006a\u0069\u0052\u004f\u0031\u0033\u0046\u005b\u0075\u006e\u0044\u0070\u0077\u0036\u0058\u004e\u0078\u0028\u0044\u0049\u007a\u0022\u003f\u003d\u0067\u0076\u0060\u004c\u002f\u0057\u002e\u0039\u0062\u004f\u0076\u004c\u0070\u005b\u0025\u003c\u0050\u007e\u003b\u004d\u0041\u0049\u004e\u0071\u003f\u0063\u003c\u003f\u004d\u0039\u003b\u0063\u0031\u0078\u006d\u0076\u0024\u0078\u0045\u004a\u004e\u0057\u0060\u0072\u0076\u003e\u0042\u005b\u004b\u0038\u0066\u0066\u0029\u0053\u005a\u002c\u0038\u0061\u0039\u0034\u004c\u005a\u0078\u0023\u0064\u007a\u0039\u005f\u0050\u006f\u004a\u0032\u0066\u003a\u0033\u0058\u003c\u005b\u003b\u0022\u003e\u005e\u0063\u005f\u0022\u0041\u0036\u006f\u0061\u0026\u0042\u0056\u003a\u0035\u002c\u0063\u0074\u0035\u0073\u0047\u003f\u0047\u007b\u007c\u0050\u0078\u0033\u0075\u007d\u006a\u0049\u006a\u0041\u0021\u0048\u004f\u002f\u0073\u005e\u0048\u002a\u0078\u003c\u0029\u0029\u0075\u007e\u0039\u0025\u003c\u0065\u0021\u0071\u007d\u0044\u0065\u0051\u0041\u0055\u0070\u004e\u0066\u0078\u0052\u0043\u006b\u007c\u0078\u006b\u005e\u0063\u0063\u0073\u003d\u004e\u0078\u0028\u006f\u0060\u0033\u003f\u0051\u0053\u0079\u0077\u0035\u0065\u002f\u003e\u003c\u0037\u0048\u0045\u006e\u0049\u0062\u0046\u004e\u004e\u0047\u0028\u0053\u0061\u0038\u0048\u0028\u0071\u0040\u0066\u003f\u007a\u005e\u0061\u0070\u0066\u005b\u0030\u0042\u0046\u007b\u002f\u0064\u0058\u0045\u0023\u0044\u0031\u0025\u0075\u0077\u0021\u0052\u002a\u0041\u0051\u003c\u0040\u0049\u0070\u002e\u004d\u006e\u002b\u0042\u006e\u0064\u003d\u0034\u0026\u007d\u0065\u0050\u0036\u0033\u0046\u0044\u006d\u004b\u0075\u0073\u003e\u0042\u0061\u003e\u0036\u0065\u004e\u003c\u005a\u005a\u0062\u0041\u0036\u0033\u0031\u0032\u0058\u007d\u007c\u0067\u002f\u0041\u0061\u007a\u006c\u006f\u003f\u0036\u0065\u003f\u007a\u003c\u007c\u0030\u0023\u003e\u005f\u004d\u0072\u0042\u0063\u0072\u005f\u0072\u0052\u007b\u0067\u006d\u004d\u0046\u0044\u0031\u007d\u007c\u004b\u0025\u0042\u0050\u0065\u0038\u006a\u006b\u0072\u006d\u0048\u0041\u0021\u0022\u0030\u006a\u007d\u006d\u0034\u0076\u0045\u0042\u004a\u0069\u0065\u0034\u0057\u007e\u002b\u0058\u003c\u003b\u004e\u003c\u005f\u0040\u0036\u0022\u0063\u005f\u007e\u004a\u0047\u005e\u003c\u0032\u0061\u0038\u0025\u0051\u0041\u007c\u0074\u003a\u006a\u007c\u0079\u003a\u0070\u006e\u005b\u0063\u007e\u0078\u0032\u0058\u0059\u005e\u0061\u0051\u0041\u007c\u0074\u003a\u006a\u0042\u0076\u0072\u007e\u002a\u0077\u005f\u002a\u0079\u0025\u0059\u0049\u0067\u0033\u0074\u0064\u0072\u007a\u005a\u0048\u006d\u007c\u0055\u007e\u0044\u005f\u0043\u0039\u0077\u0056\u003c\u005f\u006f\u0040\u0075\u0056\u0030\u006c\u0075\u0047\u0070\u0061\u0026\u0056\u0051\u0071\u0040\u0033\u002b\u0026\u0065\u0047\u003d\u0037\u0041\u0054\u0048\u006b\u004d\u0054\u004b\u003c\u007a\u005f\u0078\u0031\u0035\u0060\u0047\u0023\u0046\u007a\u0079\u0079\u0032\u0067\u0033\u0066\u0042\u0033\u0024\u006b\u002e\u0034\u005b\u003a\u0079\u0059\u006e\u004c\u0067\u0051\u005f\u0033\u006b\u0056\u0030\u0060\u007c\u0073\u0030\u007e\u007c\u007d\u002e\u0034\u0021\u0034\u0040\u0058\u0022\u003a\u0033\u0026\u002f\u006d\u0021\u002f\u0048\u0029\u0048\u0024\u0073\u0045\u0053\u003e\u007e\u002a\u0064\u007e\u0061\u007c\u0053\u0051\u007c\u003f\u0043\u0033\u004d\u007e\u0031\u004e\u0049\u0068\u006f\u002c\u0065\u0043\u003d\u004d\u002e\u0072\u007a\u005e\u0042\u006b\u0074\u0073\u0065\u0046\u004e\u0044\u0059\u002c\u0064\u002c\u0061\u0034\u004d\u0066\u0061\u0067\u002c\u005b\u0029\u0058\u0063\u005b\u0032\u0041\u006f\u0073\u0034\u0064\u0053\u006c\u0056\u0079\u0067\u003d\u0079\u004a\u004e\u004e\u0065\u004b\u0068\u0069\u007c\u0035\u006b\u003b\u0049\u0067\u005f\u006f\u005e\u005e\u0062\u005f\u0066\u0046\u005a\u0043\u0046\u0022\u0074\u0049\u0022\u0051\u006b\u0072\u0075\u006f\u004e\u0040\u0067\u0079\u0040\u005e\u005b\u005f\u007b\u0050\u006f\u007a\u004e\u0059\u004e\u007b\u005d\u0022\u0077\u002b\u0054\u0072\u0037\u004a\u006d\u003b\u0035\u003a\u004b\u0078\u0029\u0025\u0036\u0032\u007c\u0045\u0061\u007a\u0053\u0037\u0076\u002c\u004c\u0050\u002f\u004c\u007d\u005f\u004e\u0043\u0025\u0038\u002f\u007d\u005e\u0026\u0060\u0038\u0061\u0040\u003a\u0029\u004a\u0026\u002a\u004d\u0032\u0045\u0021\u002f\u004f\u0035\u0076\u003e\u0040\u0062\u0078\u007b\u003b\u0065\u0078\u0042\u005b\u0046\u0026\u0037\u0064\u0070\u003c\u002a\u004f\u0078\u0038\u002a\u0071\u005d\u003c\u007a\u0075\u0055\u0046\u0032\u006c\u0041\u0025\u0066\u0057\u002b\u002a\u004e\u0069\u0043\u0021\u0051\u0068\u0040\u0055\u0063\u003c\u004a\u0070\u0042\u007e\u0061\u007e\u005a\u005d\u004b\u0033\u002f\u0059\u0025\u004b\u007c\u006b\u0078\u0076\u0062\u0026\u0041\u0060\u004c\u004a\u0036\u0062\u0037\u006a\u0062\u0035\u0045\u003d\u005d\u0056\u0062\u0075\u007e\u0047\u0025\u003e\u006d\u005e\u002b\u0072\u0053\u0041\u0045\u0026\u0065\u004d\u0053\u0062\u0041\u0038\u005d\u0060\u0058\u0042\u0037\u0047\u0062\u004b\u0075\u004e\u004d\u002f\u002a\u0064\u007e\u0025\u0056\u0040\u006c\u006d\u0037\u0028\u0047\u0060\u004c\u007d\u004d\u006b\u0067\u0025\u0048\u0059\u0036\u002f\u002f\u0050\u0065\u0041\u006e\u0031\u0042\u003f\u0071\u0068\u003c\u0077\u005a\u003c\u005d\u0045\u002c\u0068\u005e\u0062\u003f\u0047\u0066\u004b\u0074\u0040\u0028\u0074\u0067\u0074\u002a\u0032\u002b\u006c\u0056\u005f\u0048\u0047\u0063\u0036\u0042\u0074\u0055\u0040\u0050\u002f\u0053\u0055\u0024\u007d\u0064\u0063\u004d\u0058\u003f\u004c\u0045\u005d\u0077\u004c\u0022\u0044\u004c\u002c\u003e\u0068\u004d\u0038\u0060\u0056\u0056\u0048\u005d\u003d\u0038\u003a\u005e\u004c\u0022\u0044\u004c\u006c\u0069\u0074\u0065\u003d\u0056\u0072\u007e\u003b\u007c\u0033\u0055\u004a\u0051\u0054\u0035\u007c\u0056\u0052\u0045\u0033\u003f\u0058\u0030\u0046\u003d\u0058\u0044\u0040\u0036\u0057\u0030\u0059\u0037\u003f\u0031\u007c\u0057\u005f\u0044\u007e\u002c\u0047\u0077\u0062\u003e\u0078\u0077\u0028\u0052\u0048\u0045\u0049\u0073\u0071\u0051\u0044\u005b\u004a\u0048\u0038\u0038\u0041\u006a\u0031\u006b\u0035\u0031\u0022\u003e\u003c\u005a\u0029\u004e\u0038\u005e\u0079\u0025\u006a\u0059\u0045\u0031\u003e\u0030\u0046\u0051\u0075\u006c\u0046\u0024\u0075\u0074\u003c\u005a\u0043\u005a\u003f\u006b\u0074\u0042\u0066\u005b\u0062\u0059\u002b\u003c\u0074\u0030\u0056\u0071\u0049\u005d\u0036\u003e\u0073\u0045\u0038\u0069\u006e\u002c\u0069\u0067\u0058\u0047\u0067\u0060\u0051\u0045\u006f\u0062\u0036\u003b\u0035\u0033\u0069\u0024\u007e\u0065\u0039\u0078\u006c\u0067\u0039\u0046\u0043\u007e\u002a\u007d\u007e\u0065\u0039\u0078\u006c\u0067\u0056\u002a\u0028\u0065\u003c\u007d\u007a\u003f\u0065\u0035\u0039\u0074\u005a\u0025\u002e\u0024\u007b\u0031\u0073\u0066\u0064\u0024\u004d\u0065\u0066\u0052\u0025\u005b\u003f\u003b\u0063\u0058\u0053\u003a\u005d\u0036\u0049\u0057\u0077\u0049\u0048\u0022\u003a\u0055\u0030\u003e\u005f\u004b\u0070\u0075\u004b\u0030\u0032\u0047\u0034\u0026\u0042\u004f\u0042\u0067\u003e\u0028\u0030\u003e\u006c\u0056\u0074\u0063\u0075\u0059\u0048\u0026\u0044\u0048\u0043\u002c\u004e\u002a\u005d\u0035\u0058\u0078\u003e\u0055\u007d\u0064\u0075\u0056\u0022\u0065\u0069\u0053\u0040\u002e\u0078\u0021\u003b\u005d\u006d\u0053\u0078\u0030\u007a\u002b\u0062\u006c\u0039\u004f\u0045\u0066\u002f\u0056\u0042\u007e\u0052\u0063\u0059\u002b\u0041\u0045\u0079\u0025\u002a\u004d\u005d\u0036\u0028\u0078\u0051\u007e\u003a\u004b\u0059\u002b\u004b\u0070\u007c\u006b\u0025\u0026\u003b\u0036\u0046\u0065\u0032\u0045\u0069\u002e\u0071\u0058\u0050\u0030\u0033\u0049\u006f\u0067\u0056\u0068\u0064\u0064\u004f\u006b\u007a\u0049\u0049\u006f\u0067\u0074\u0048\u0023\u006b\u004f\u0045\u0062\u0028\u004b\u003c\u0070\u0053\u007a\u0066\u006b\u0028\u0057\u007e\u0024\u002a\u007a\u0054\u006a\u004c\u0044\u002b\u004e\u0037\u003a\u006d\u003d\u0049\u0067\u003f\u0076\u003e\u0045\u0026\u0052\u002a\u0069\u0023\u007a\u003f\u003d\u0073\u003b\u0042\u0039\u003a\u0043\u0040\u0029\u006a\u0022\u0038\u0025\u006d\u0075\u0066\u007e\u006c\u0061\u0069\u003a\u005f\u002c\u007b\u002a\u0068\u0067\u005b\u007c\u0023\u0034\u0074\u0037\u0063\u0061\u002a\u0054\u0057\u003e\u0068\u006a\u0025\u0067\u0060\u004d\u0039\u0056\u003f\u0076\u003e\u005a\u002c\u006e\u007c\u0028\u0035\u0076\u0073\u005b\u0070\u0045\u0033\u0043\u005e\u005e\u003d\u006e\u006f\u006b\u005e\u007a\u0074\u003c\u0060\u002c\u006e\u007c\u0069\u0045\u0023\u002c\u0061\u007b\u0058\u0078\u0025\u0063\u0078\u0023\u005f\u0068\u0042\u007d\u0022\u0073\u003c\u006f\u0034\u003f\u0066\u0074\u0037\u0067\u0054\u0078\u0030\u0028\u0069\u0050\u006d\u007d\u005f\u0044\u0031\u002c\u0050\u002a\u006e\u0023\u0043\u002f\u0078\u0079\u0060\u0025\u002c\u0031\u006a\u0022\u005a\u005a\u007b\u0064\u0050\u0078\u0051\u007d\u004e\u0071\u006a\u0062\u0021\u0032\u0059\u0070\u0035\u0058\u0036\u0026\u002c\u003c\u006b\u004f\u0058\u0037\u0059\u003c\u005b\u002f\u003b\u006b\u002c\u003e\u0031\u003f\u0064\u0069\u004e\u0028\u0051\u003f\u0071\u005d\u0036\u006b\u0030\u002b\u0040\u0039\u004d\u003f\u0045\u005f\u0043\u0039\u007c\u007d\u007e\u0045\u0026\u0035\u005e\u007a\u0074\u003c\u0060\u002c\u003c\u0059\u0058\u0023\u0041\u005f\u005a\u0064\u002e\u0032\u0066\u0074\u0023\u004a\u0045\u0026\u004c\u006e\u004f\u0056\u0057\u005a\u0038\u0070\u0060\u0038\u0048\u006c\u0023\u0072\u0055\u002e\u006c\u004e\u0043\u0054\u0036\u005d\u0040\u0024\u0052\u0022\u0074\u0031\u002f\u0071\u0077\u0062\u0023\u007a\u0032\u0024\u0047\u0060\u004c\u004a\u0031\u0055\u004e\u0032\u007e\u0057\u004a\u0050\u0042\u0035\u0077\u0028\u0057\u007e\u0032\u0033\u0028\u0076\u0042\u0028\u0055\u007b\u0036\u0064\u0021\u0057\u0038\u007a\u0075\u0062\u003b\u0037\u006b\u0021\u007e\u0034\u0046\u005f\u0063\u0061\u0065\u002b\u0028\u006a\u0044\u006c\u0068\u0033\u003c\u006d\u002b\u0056\u0050\u005e\u0024\u0038\u0053\u0039\u006a\u0058\u0033\u0051\u0060\u0065\u004d\u007a\u002e\u0060\u0034\u0066\u0023\u0033\u0035\u0041\u0074\u0023\u0022\u0025\u003f\u0035\u0077